"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command "@'
const fs = require('node:fs');
const assert = require('node:assert/strict');
function read(file) {
  const lines = fs.readFileSync(file, 'utf8').trim().split(/\\r?\\n/);
  const header = lines.shift().split(',');
  return lines.map(line => Object.fromEntries(line.split(',').map((value, index) => [header[index], value])));
}
const pairs = read('evidence/pairs.csv');
function outcomes(file) {
  const rows = read(file);
  assert.equal(new Set(rows.map(row => row.pair_id)).size, rows.length);
  assert.deepEqual(rows.map(row => row.pair_id).sort(), pairs.map(row => row.pair_id).sort());
  return new Map(rows.map(row => {
    assert.ok(['true', 'false'].includes(row.correct));
    assert.ok(['true', 'false'].includes(row.assisted));
    const seconds = row.seconds === '' ? null : Number(row.seconds);
    assert.ok(seconds === null || (Number.isFinite(seconds) && seconds > 0));
    return [row.pair_id, { seconds, correct: row.correct === 'true', assisted: row.assisted === 'true' }];
  }));
}
const reference = outcomes('evidence/reference.csv');
const guide = outcomes('evidence/guide.csv');
const matched = pairs.map(pair => {
  const r = reference.get(pair.pair_id), g = guide.get(pair.pair_id);
  const eligible = r.seconds "'!== null && g.seconds !== null;
  return { ...pair, reference: r, guide: g, eligible, saved: eligible ? r.seconds - g.seconds : null };
});
const eligible = matched.filter(row => row.eligible);
const sum = (rows, select) => rows.reduce((total, row) => total + select(row), 0);
const metrics = {
  eligible_time_pairs: eligible.length,
  reference_seconds: sum(eligible, row => row.reference.seconds),
  guide_seconds: sum(eligible, row => row.guide.seconds),
  time_saved_seconds: sum(eligible, row => row.saved),
  faster_pairs: eligible.filter(row => row.saved > 0).length,
  slower_pairs: eligible.filter(row => row.saved < 0).length,
  tied_pairs: eligible.filter(row => row.saved === 0).length,
  accuracy_pairs: matched.length,
  reference_correct: matched.filter(row => row.reference.correct).length,
  guide_correct: matched.filter(row => row.guide.correct).length
};
const groups = key => Object.fromEntries([...new Set(matched.map(row => row[key]))].map(value => {
  const rows = eligible.filter(row => row[key] === value);
  return [value, { eligible: rows.length, reference: sum(rows, row => row.reference.seconds), guide: sum(rows, row => row.guide.seconds), saved: sum(rows, row => row.saved) }];
}));
const accuracy = { both_correct: 0, reference_only: 0, guide_only: 0, neither_correct: 0 };
for (const row of matched) accuracy[row.reference.correct ? (row.guide.correct ? '"'both_correct' : 'reference_only') : (row.guide.correct ? 'guide_only' : 'neither_correct')]++;
console.log(JSON.stringify({metrics, percentage_saving: metrics.time_saved_seconds / metrics.reference_seconds * 100, matched, by_volunteer: groups('volunteer_id'), by_first_format: groups('first_format'), accuracy, assistance: { reference: matched.filter(row => row.reference.assisted).map(row => row.pair_id), guide: matched.filter(row => row.guide.assisted).map(row => row.pair_id) }}, null, 2));
'@ | node"

